<?php require_once __DIR__.'/../app/core/bootstrap.php';if(current_user())redirect('index.php');$title='Operator application';$error='';if(is_post()){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Complete the form with a valid email and password.';else{$st=db()->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$st->bind_param('s',$email);$st->execute();if($st->get_result()->fetch_assoc())$error='That email is already registered.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$role='operator';$status='pending';$st=db()->prepare('INSERT INTO users(name,email,phone,password_hash,role,status) VALUES(?,?,?,?,?,?)');$st->bind_param('ssssss',$name,$email,$phone,$hash,$role,$status);$st->execute();flash('success','Operator application submitted. An admin must activate the account.');redirect('login.php');}}}require __DIR__.'/../app/views/header.php';?><div class="form-shell"><div class="form-card"><div class="eyebrow" style="color:var(--green)">Partner with Wildvista</div><h1 style="font-family:Georgia,serif;font-size:42px">Apply as an operator</h1><?php if($error):?><div class="toast error" style="position:relative;top:auto;right:auto;margin:15px 0;animation:none"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><label>Name / business</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Phone</label><input name="phone"><label>Password</label><input type="password" name="password" required minlength="8"><button class="btn btn-dark" style="width:100%;margin-top:18px">Submit application</button></form><p class="muted">Admin reviews your account before your portal becomes active.</p></div></div><?php require __DIR__.'/../app/views/footer.php';?>
